-- Import Hisnul Mouslim cours 2 (révision): 25 questions "Invocations du réveil et de l'habillement" depuis cours2_hin.json.
-- tenant Abou Abdelwahab (qawaid.abouabdelwahab.com). Remplace le contenu de cours 2.
-- À exécuter une seule fois.

do $$ declare t uuid:='6badf254-27a3-4f69-98e3-e67caa917371'; c uuid;
begin
  select id into c from quiz_courses where tenant_id=t and subject='Hisnul Mouslim' and number=2;
  if c is null then
      values (t,'Hisnul Mouslim',2,'Invocations du réveil et de l''habillement',2) returning id into c;
  else
    update quiz_courses set title='Invocations du réveil et de l''habillement' where id=c;
    delete from quiz_questions where course_id=c;
  end if;
end $$;
